61	  constructor() {
62	    const savedConfig = readGlobalConfig()?.cloud || {};
63	    this.config = {
64	      appUrl: savedConfig.appUrl || 'https://www.promptfoo.app',
65	      apiHost: savedConfig.apiHost,
66	      apiKey: savedConfig.apiKey,
67	      sharing: savedConfig.sharing,
68	      currentOrganizationId: savedConfig.currentOrganizationId,
69	      currentTeamId: savedConfig.currentTeamId,
70	      teams: savedConfig.teams,
71	    };
72	  }
