82	  /**
83	   * Returns the API host from config file, PROMPTFOO_CLOUD_API_URL environment variable,
84	   * or defaults to the standard cloud API host.
85	   * Config file takes precedence over environment variable.
86	   */
87	  private resolveApiHost(): string {
88	    return this.config.apiHost || process.env.PROMPTFOO_CLOUD_API_URL || API_HOST;
