19	/**
20	 * Makes an authenticated HTTP request to the PromptFoo Cloud API.
21	 * @param path - The API endpoint path (with or without leading slash)
22	 * @param method - HTTP method (GET, POST, PUT, DELETE, etc.)
23	 * @param body - Optional request body that will be JSON stringified
24	 * @returns Promise resolving to the fetch Response object
25	 * @throws Error if the request fails due to network or other issues
26	 */
27	export function makeRequest(path: string, method: string, body?: any): Promise<Response> {
28	  const apiHost = cloudConfig.getApiHost();
29	  const apiKey = cloudConfig.getApiKey();
30	  const url = `${apiHost}/api/v1/${path.startsWith('/') ? path.slice(1) : path}`;
31	  try {
32	    return fetchWithProxy(url, {
33	      method,
34	      body: JSON.stringify(body),
35	      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
36	    });
37	  } catch (e) {
38	    logger.error(`[Cloud] Failed to make request to ${url}: ${e}`);
39	    if ((e as any).cause) {
40	      logger.error(`Cause: ${(e as any).cause}`);
41	    }
42	    throw e;
43	  }
44	}
