   * Validates an API token against the cloud API without persisting any configuration.
   * @param token - The API token to validate.
   * @param apiHost - The API host to validate against.
   * @returns The user, organization, app, and optional license status from the API response.
   * @throws Error if the token is invalid or the request fails.
   */
  async validateApiToken(
    token: string,
    apiHost: string,
  ): Promise<{
    user: CloudUser;
    organization: CloudOrganization;
    app: CloudApp;
    hasActiveLicense?: boolean;
  }> {
    try {
      const { fetchWithProxy } = await import('../util/fetch');
      const response = await fetchWithProxy(`${apiHost}/api/v1/users/me`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        const errorMessage = await response.text();
        logger.error(
          `[Cloud] Failed to validate API token: ${errorMessage}. HTTP Status: ${response.status} - ${response.statusText}.`,
        );
        throw new Error('Failed to validate API token: ' + response.statusText);
      }

      const { user, organization, app, hasActiveLicense } = await response.json();
      return { user, organization, app, hasActiveLicense };
    } catch (err) {
      const error = err as Error & { cause?: string };
      const errorMessage = error instanceof Error ? error.message : String(error);
      logger.error(`[Cloud] Failed to validate API token with host ${apiHost}: ${errorMessage}`);
      if (error.cause) {
        logger.error(`Cause: ${error.cause}`);
      }
      throw error;
    }
  }

  /**
   * Persists a previously validated API token and related configuration (API host,
   * app URL, license/sharing status) to the stored configuration. This is a synchronous
   * operation and does not call the cloud API.
   * @param token - The validated API token.
   * @param apiHost - The API host the token was validated against.
   * @param user - The user object returned by `validateApiToken`.
   * @param app - The app object returned by `validateApiToken`.
   * @param hasActiveLicense - The license status returned by `validateApiToken`.
   */
  saveValidatedApiToken(
    token: string,
    apiHost: string,
    user: CloudUser,
    app: CloudApp,
    hasActiveLicense?: boolean,
  ): void {
    this.config.apiKey = token;
    this.config.apiHost = apiHost;
    this.config.appUrl = app.url;
    if (typeof hasActiveLicense === 'boolean') {
      const createdAt = user?.createdAt ? new Date(user.createdAt) : null;
      const isGrandfathered = createdAt != null && createdAt < SHARING_CUTOFF_DATE;
      this.config.sharing = hasActiveLicense || isGrandfathered;
    }
    this.saveConfig();
  }

  async validateAndSetApiToken(
    token: string,
    apiHost: string,
  ): Promise<{
    user: CloudUser;
    organization: CloudOrganization;
    app: CloudApp;
    hasActiveLicense: boolean;
  }> {
    const { user, organization, app, hasActiveLicense } = await this.validateApiToken(
      token,
      apiHost,
    );
    this.saveValidatedApiToken(token, apiHost, user, app, hasActiveLicense);

    return {
