interface LoginTeam {
  id: string;
  name: string;
  slug: string;
  organizationId: string;
  createdAt: string;
  updatedAt: string;
}

/**
 * Thrown during login when a requested organization has no accessible teams.
 * The message is already fully formatted, so it is logged verbatim.
 */
class OrgNotFoundError extends Error {}

/** Returns the team with the earliest createdAt date. */
function oldestTeam(teams: LoginTeam[]): LoginTeam {
  return [...teams].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
  )[0];
}

/** Finds a team by id, then case-insensitive display name, then slug (in that priority order). */
function findTeamByIdentifier(teams: LoginTeam[], identifier: string): LoginTeam | undefined {
  return (
    teams.find((t) => t.id === identifier) ||
    teams.find((t) => t.name.toLowerCase() === identifier.toLowerCase()) ||
    teams.find((t) => t.slug === identifier)
  );
}

/**
 * Selects a team from the given list. Single-team lists resolve immediately.
 * When multiple teams exist, interactive environments prompt the user, while
 * non-interactive environments (or a cancelled prompt) default to the oldest team.
 */
async function selectTeamFromList(teams: LoginTeam[]): Promise<LoginTeam | undefined> {
  if (teams.length === 0) {
    return undefined;
  }
  if (teams.length === 1) {
    return teams[0];
  }
  if (isNonInteractive()) {
    // Non-interactive: default to the oldest team without an extra API call.
    return oldestTeam(teams);
  }
  logger.info('');
  try {
    const answer = await select({
      message: 'Select a team to use:',
      choices: teams.map((team) => ({
        name: team.name,
        value: team.id,
        description: team.slug,
      })),
    });
    return teams.find((t) => t.id === answer) ?? oldestTeam(teams);
  } catch {
    // User cancelled (Ctrl+C) - fall back to the oldest team.
    return oldestTeam(teams);
  }
}

