  options: { org?: string; team?: string },
): Promise<{ resolvedOrgId: string; selectedTeam?: LoginTeam }> {
  if (options.org) {
    // --org specified: restrict resolution to teams in that organization.
    const orgTeams = allTeams.filter((t) => t.organizationId === options.org);
    if (orgTeams.length === 0) {
      const availableOrgs: string[] = [];
      for (const id of [fallbackOrgId, ...allTeams.map((t) => t.organizationId)]) {
        if (!availableOrgs.includes(id)) {
          availableOrgs.push(id);
