    expect(cloudConfig.setCurrentTeamId).toHaveBeenCalledWith('t2', 'orgB');
    expect(cloudConfig.saveValidatedApiToken).toHaveBeenCalledWith('k', 'https://api.host', user, app, false);
    expect(setUserEmail).toHaveBeenCalledWith('a@b.com');
    expect(process.exitCode).toBeUndefined();
  });

  it('--org filters teams; org not found errors without saving', async () => {
    vi.mocked(getUserTeams).mockResolvedValue([
      team('t1', 'Default', 'default', 'orgA', '2024-01-01'),
      team('t2', 'Security', 'security', 'orgB', '2024-01-02'),
    ]);
    await getLogin(program).parseAsync(['n', 't', '--api-key', 'k', '--org', 'orgZ']);
    const errMsg = vi.mocked(logger.error).mock.calls.map((c) => String(c[0])).join('\n');
    expect(errMsg).toContain(
      "Authentication failed: Organization 'orgZ' not found in your accessible teams. Available organizations: orgA, orgB",
    );
    expect(process.exitCode).toBe(1);
    expect(cloudConfig.saveValidatedApiToken).not.toHaveBeenCalled();
    expect(setUserEmail).not.toHaveBeenCalled();
