    ]);
    await getLogin(program).parseAsync(['n', 't', '--api-key', 'k', '--org', 'orgA', '--team', 'security']);
    expect(cloudConfig.setCurrentTeamId).toHaveBeenCalledWith('t1', 'orgA');
  });

  it('no flags, default org empty -> resolves org of oldest team + logs org id', async () => {
    vi.mocked(getUserTeams).mockResolvedValue([
      team('t3', 'Newer', 'newer', 'orgC', '2024-05-01'),
      team('t2', 'Oldest', 'oldest', 'orgB', '2024-01-02'),
    ]);
    await getLogin(program).parseAsync(['n', 't', '--api-key', 'k']);
    expect(cloudConfig.setCurrentOrganization).toHaveBeenCalledWith('orgB');
    const infos = vi.mocked(logger.info).mock.calls.map((c) => String(c[0]));
    expect(infos.some((m) => m.includes('Organization:') && m.includes('orgB'))).toBe(true);
    expect(cloudConfig.setCurrentTeamId).toHaveBeenCalledWith('t2', 'orgB');
  });

