    const cloudMod: any = await import('../../src/util/cloud');
    vi.mocked(getUserTeams).mockResolvedValue([
      team('t1', 'B', 'b', 'orgA', '2024-03-01'),
      team('t2', 'A', 'a', 'orgA', '2024-01-01'),
    ]);
    await getLogin(program).parseAsync(['n', 't', '--api-key', 'k']);
    expect(cloudConfig.setCurrentTeamId).toHaveBeenCalledWith('t2', 'orgA');
    expect(cloudMod.getDefaultTeam).not.toHaveBeenCalled();
  });

