    vi.mocked(getUserTeams).mockResolvedValue([team('t1', 'Sec', 'security', 'orgA', '2024-01-01')]);
    await getLogin(program).parseAsync(['n', 't', '--api-key', 'k', '--host', 'https://custom', '--team', 'security']);
    expect(getUserTeams).toHaveBeenCalledWith('https://custom', 'k');
    expect(cloudConfig.validateApiToken).toHaveBeenCalledWith('k', 'https://custom');
  });
