nization: ${chalk.cyan(organization.name)}`);\n          } else {\n            logger.info(`Organization: ${chalk.cyan(resolvedOrgId)}`);\n          }\n          logger.info(`App: ${chalk.cyan(cloudConfig.getAppUrl())}`);\n          if (selectedTeam) {\n            logger.info(`Team: ${chalk.cyan(selectedTeam.name)}`);\n          }\n          return;", "numLines": 55, "startLine": 163, "totalLines": 455}}
